import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validarProdutos, calcularTotal, formatarTotal, processarPedido } from './solution.mjs';

test('camada de cálculo: soma preço x quantidade', () => {
  assert.equal(calcularTotal([
    { nome: 'Café', preco: 8, quantidade: 2 },
    { nome: 'Bolo', preco: 12.5, quantidade: 1 },
  ]), 28.5);
  assert.equal(calcularTotal([]), 0);
});

test('camada de formatação: duas casas decimais', () => {
  assert.equal(formatarTotal(28.5), 'R$ 28.50');
  assert.equal(formatarTotal(0), 'R$ 0.00');
});

test('processarPedido compõe as camadas na ordem certa', () => {
  assert.equal(processarPedido([
    { nome: 'Café', preco: 8, quantidade: 2 },
    { nome: 'Bolo', preco: 12.5, quantidade: 1 },
  ]), 'R$ 28.50');
  assert.equal(processarPedido([]), 'R$ 0.00');
});

test('camada de validação recusa item inválido antes de calcular', () => {
  validarProdutos([{ nome: 'Café', preco: 8, quantidade: 1 }]); // válido não lança
  assert.throws(() => processarPedido([{ nome: '', preco: 8, quantidade: 1 }]));
  assert.throws(() => processarPedido([{ nome: 'Café', preco: -1, quantidade: 1 }]));
  assert.throws(() => processarPedido([{ nome: 'Café', preco: 8, quantidade: 0 }]));
  assert.throws(() => validarProdutos('não é lista'));
});

