// Cada função tem UMA responsabilidade; processarPedido apenas compõe as camadas.
export function validarProdutos(produtos) {
  if (!Array.isArray(produtos)) {
    throw new Error('produtos precisa ser uma lista');
  }
  for (const item of produtos) {
    if (typeof item?.nome !== 'string' || item.nome.trim() === '') {
      throw new Error('todo item precisa de nome (texto não vazio)');
    }
    if (typeof item?.preco !== 'number' || item.preco < 0) {
      throw new Error('todo item precisa de preco (número maior ou igual a 0)');
    }
    if (!Number.isInteger(item?.quantidade) || item.quantidade < 1) {
      throw new Error('todo item precisa de quantidade (inteiro maior ou igual a 1)');
    }
  }
}

export function calcularTotal(produtos) {
  // Camada de cálculo: pura, sem validação e sem formatação.
  return produtos.reduce((soma, item) => soma + item.preco * item.quantidade, 0);
}

export function formatarTotal(total) {
  // Camada de apresentação: pura, sem regras de negócio.
  return `R$ ${total.toFixed(2)}`;
}

export function processarPedido(produtos) {
  // Composição das camadas: validar -> calcular -> formatar.
  validarProdutos(produtos);
  return formatarTotal(calcularTotal(produtos));
}
